% MATLAB and PMKS+ comparison, final release 2026-09-11
clc;
clear;

%% Load MATLAB results
show_plots = true;
script_folder = fileparts(mfilename('fullpath'));
source_result_file = fullfile(script_folder,'results_matlab','classroom_results.mat');
assert(isfile(source_result_file),'Run main.m first.');
MATLAB = load(source_result_file);
Motion = MATLAB.Motion; time = MATLAB.time;
assert(iscolumn(time) && time(1)==0 && all(diff(time)>0));
output_folder = fullfile(script_folder,'results_pmks_comparison');
if ~exist(output_folder,'dir'), mkdir(output_folder); end

%% Hard-coded native PMKS data
PMKS = embedded_pmks_data;
reference_joints = [1.4 .485 0;1.67 .990 0;.255 1.035 0;.285 .055 0; ...
    .195 2.540 0;-.980 2.570 0;.050 .200 0;-1.714591427659256 4.260273479177123 0];
if ~isequal(size(MATLAB.FirstPosition.Joints),[8 3]) ...
        || max(abs(MATLAB.FirstPosition.Joints-reference_joints),[],'all')>1e-10 ...
        || abs(time(end)-2.592)>1e-10 ...
        || max(abs(Motion.omega_AB-repmat([0 0 2*pi/2.592],numel(time),1)),[],'all')>1e-10 ...
        || any(Motion.alpha_AB~=0,'all')
    warning('PMKS:ReferenceSetupMismatch','Reference requires the saved geometry and steady input.');
    PMKS=struct;
end
reference_COM=[1.536733363916078 .7407420325097016 0; ...
    .9646412340420778 1.012431904217743 0;.23975803228598874 1.3041809974368663 0; ...
    -.39019221024183426 2.554941077708302 0;-.830871977822548 2.226860764504309 0];
if max(abs(MATLAB.FirstPosition.COM-reference_COM),[],'all')>1e-10
    warning('PMKS:ReferenceCOMMismatch','COM and force references require the saved CAD centers.');
    PMKS=remove_references(PMKS,true,true);
end
valid_static=isequal(MATLAB.P.mass,[8.03 19.41 33.48 16.16 59.68]) ...
    && isequal(MATLAB.P.g_vector,[0;-9.81;0]) ...
    && isequal(MATLAB.FirstPosition.Q_static,[0 -200 0]);
if ~valid_static
    warning('PMKS:ReferenceStaticSetupMismatch','Force references require the saved mass, gravity and load.');
    PMKS=remove_references(PMKS,false,true);
end

%% Initial position
Tables=first_position_tables(MATLAB,PMKS,output_folder);
for name=fieldnames(Tables)', disp(name{1}); disp(Tables.(name{1})); end

%% Complete cycle and report figures
PMKSComparison=compare_pmks(MATLAB,PMKS,output_folder);
disp(PMKSComparison);
plot_comparison(MATLAB,PMKS,show_plots,output_folder);
save(fullfile(output_folder,'comparison_results.mat'),'Tables','PMKS', ...
    'PMKSComparison','source_result_file');
fprintf('All reference arrays are native PMKS CSV samples captured on 2026-09-11 UTC.\n');
fprintf('No browser, external CSV or additional PMKS calculation is needed.\n');
fprintf('Newton second-law forces remain MATLAB-only in the report.\n');

%% Local functions
function P=remove_references(P,com,force)
for name=fieldnames(P)'
    key=name{1};
    if (com && startsWith(key,'a_S')) || (force && startsWith(key,'static_'))
        P=rmfield(P,key);
    end
end
end

function T=first_position_tables(M,P,out)
names={'Static','AngularVelocity','AngularAcceleration','JointVelocity','JointAcceleration','COMAcceleration'};
for k=1:numel(names)
    name=names{k}; t=M.Tables.(name); N=height(t);
    t.PMKS=nan(N,1); t.Source=repmat("No matching reference",N,1);
    for j=1:N
        q=char(t.Quantity(j)); magnitude=startsWith(q,'|');
        if strcmp(q,'T_z'), key='static_T'; comp=3;
        elseif strcmp(name,'Static')
            q=erase(q,'|'); key=['static_' q(1:3)];
            if magnitude, comp=0; else, comp=1+strcmp(q(end),'y'); end
        elseif startsWith(name,'Angular')
            key=q(1:end-2); comp=3;
        else
            q=erase(q,'|');
            if magnitude, key=q; comp=0; else, key=q(1:end-1); comp=1+strcmp(q(end),'y'); end
        end
        if isfield(P,key)
            e=P.(key);
            if comp==0, t.PMKS(j)=e.magnitude(1); else, t.PMKS(j)=e.vector(1,comp); end
            t.Source(j)=string(e.source);
        end
    end
    t.AbsDifference=abs(t.MATLAB-t.PMKS);
    T.(name)=t;
    writetable(t,fullfile(out,['FirstPosition_' name '.csv']));
end
end

function [values,components]=matlab_series(M,key)
if strcmp(key,'static_T'), values=[zeros(numel(M.time),2),M.static_history(:,15)]; components=3;
elseif startsWith(key,'static_F_')
    j=double(key(end))-double('A')+1;
    values=[M.static_history(:,2*j-1:2*j),zeros(numel(M.time),1)]; components=1:2;
else
    values=M.Motion.(key);
    if startsWith(key,'omega_') || startsWith(key,'alpha_'), components=3; else, components=1:2; end
end
end

function T=compare_pmks(M,P,out)
series=strings(0,1); unit=series; source=series; count=[]; error=[]; percent=[];
for field=fieldnames(P)'
    key=field{1}; entry=P.(key); [values,components]=matlab_series(M,key);
    for c=components
        predicted=interp1(M.time,values(:,c),entry.time,'linear');
        difference=predicted-entry.vector(:,c); peak=max(abs(predicted));
        err=max(abs(difference)); pct=NaN; if peak>1e-12, pct=100*err/peak; end
        series(end+1,1)=string(key)+"_"+string(char('x'+c-1));
        unit(end+1,1)=string(entry.unit); source(end+1,1)=string(entry.source);
        count(end+1,1)=numel(entry.time); error(end+1,1)=err; percent(end+1,1)=pct;
    end
end
T=table(series,unit,count,error,percent,source,'VariableNames', ...
    {'Series','Unit','Samples','MaxAbsDifference','PeakScaledPercent','Source'});
writetable(T,fullfile(out,'PMKS_FullCycle_Comparison.csv'));
end

function plot_comparison(M,P,show,out)
if show, visibility='on'; else, visibility='off'; end
names={'AB','BC','DCE','EF','GFH'};
colors=[0 .35 .65;.85 .30 .05;.10 .55 .30;.55 .25 .65;.55 .40 .05];
for k=1:2
    if k==1, prefix='omega_'; label='Angular velocity (rad/s)'; file='01_angular_velocity';
    else, prefix='alpha_'; label='Angular acceleration (rad/s^2)'; file='02_angular_acceleration'; end
    [f,ax]=report_axes(label,visibility);
    for j=1:5
        key=[prefix names{j}];
        overlay(ax,M.time,M.Motion.(key)(:,3),P,key,3,colors(j,:),names{j});
    end
    finish_plot(f,ax,label,out,file);
end
for k=1:2
    if k==1, key='v_H'; label='H velocity (m/s)'; file='03_H_velocity';
    else, key='a_H'; label='H acceleration (m/s^2)'; file='04_H_acceleration'; end
    [f,ax]=report_axes(label,visibility);
    for c=1:2, overlay(ax,M.time,M.Motion.(key)(:,c),P,key,c,colors(c,:),[char('x'+c-1) ' component']); end
    finish_plot(f,ax,label,out,file);
end
[f,ax]=report_axes('Mass-center acceleration',visibility);
for j=[3 5]
    key=sprintf('a_S%d',j); a=M.Motion.(key);
    overlay(ax,M.time,vecnorm(a,2,2),P,key,0,colors(1+(j==5),:),sprintf('S%d (%s)',j,names{j}));
end
finish_plot(f,ax,'Acceleration magnitude (m/s^2)',out,'05_COM_acceleration');
[f,ax]=report_axes('Static input torque',visibility);
overlay(ax,M.time,M.static_history(:,15),P,'static_T',3,colors(1,:),'Static torque');
finish_plot(f,ax,'Input torque (N m)',out,'06_static_torque');
[f,ax]=report_axes('Static and dynamic input torque',visibility);
plot(ax,M.time,M.static_history(:,15),'Color',colors(1,:),'LineWidth',1.2,'DisplayName','Static');
plot(ax,M.time,M.dynamic_history(:,15),'Color',colors(2,:),'LineWidth',1.2,'DisplayName','Newton second law');
finish_plot(f,ax,'Input torque (N m)',out,'07_dynamic_torque',false);
end

function [f,ax]=report_axes(name,visibility)
f=figure('Name',name,'NumberTitle','off','Visible',visibility,'Color','w', ...
    'Units','inches','Position',[1 1 3.5 2.7]);
ax=axes(f,'FontName','Times New Roman','FontSize',9,'LineWidth',.7);
hold(ax,'on'); box(ax,'on'); grid(ax,'on'); ax.GridAlpha=.15;
end

function overlay(ax,time,value,P,key,component,color,label)
plot(ax,time,value,'Color',color,'LineWidth',1.2,'DisplayName',label);
if isfield(P,key)
    e=P.(key); if component==0, v=e.magnitude; else, v=e.vector(:,component); end
    plot(ax,e.time,v,'--','Color',color,'LineWidth',.85,'HandleVisibility','off');
    index=1:12:numel(e.time);
    plot(ax,e.time(index),v(index),'o','Color',color,'MarkerSize',3, ...
        'LineWidth',.7,'HandleVisibility','off');
else
    text(ax,.04,.96,'Matching PMKS data unavailable','Units','normalized', ...
        'FontSize',8,'VerticalAlignment','top');
end
end

function finish_plot(f,ax,label,out,file,methods)
if nargin<6, methods=true; end
if methods
    plot(ax,NaN,NaN,'k-','DisplayName','MATLAB','LineWidth',1.2);
    plot(ax,NaN,NaN,'ko--','DisplayName','PMKS+','MarkerSize',3,'LineWidth',.8);
end
xlabel(ax,'Time (s)'); ylabel(ax,label); xlim(ax,[0 2.592]); xticks(ax,[0 .5 1 1.5 2 2.592]);
legend(ax,'Location','northoutside','NumColumns',3,'FontSize',8,'Box','off');
if verLessThan('matlab','25.1')
    exportgraphics(f,fullfile(out,[file '.png']),'Resolution',300);
else
    exportgraphics(f,fullfile(out,[file '.png']),'Resolution',300,'Padding',12);
end
end

